  if(updater.changelog?.githubHistory && (!updater.changelog.githubHistory.owner||!updater.changelog.githubHistory.repo||!updater.changelog.githubHistory.path)) errors.push('changelog.githubHistory benötigt owner, repo und path');
  if(updater.changelog?.githubHistory?.commits!==undefined && (!Number.isInteger(updater.changelog.githubHistory.commits)||updater.changelog.githubHistory.commits<1||updater.changelog.githubHistory.commits>30)) errors.push('changelog.githubHistory.commits muss zwischen 1 und 30 liegen');
