  if(meta.compatibility?.minimumAtmosphere&&!/^\d+(?:\.\d+)*$/.test(meta.compatibility.minimumAtmosphere)) errors.push('compatibility.minimumAtmosphere muss eine numerische Version sein');
  if(meta.compatibility?.minimumFirmware&&!/^\d+(?:\.\d+)*$/.test(meta.compatibility.minimumFirmware)) errors.push('compatibility.minimumFirmware muss eine numerische Version sein');
